const inv = $('Get Open Invoices').first().json;
const entries = inv.value || (Array.isArray(inv) ? inv : []);
const today = new Date().toISOString().slice(0, 10);
// Per-run override from the HubSpot page ("SW Make Job") beats the Settings node.
let ov = null; try { ov = $('SW Make Job').first().json; } catch (e) {}
let CUTOFF = '2024-12-31'; // must have a remaining invoice dated on/before this (blank = any overdue)
if (ov && ov.oldestInvoice !== undefined) { CUTOFF = String(ov.oldestInvoice).slice(0, 10); }
else { try { const v = $('Settings').first().json.Oldest_Open_Invoice; if (v !== undefined) CUTOFF = String(v == null ? '' : v).slice(0, 10); } catch (e) {} }
let MIN = 1000;
if (ov && ov.minBalance !== undefined && ov.minBalance !== '') { const m = Number(ov.minBalance); if (isFinite(m)) MIN = m; }
else { try { const v = Number($('Settings').first().json.Min_Overdue_Balance); if (isFinite(v)) MIN = v; } catch (e) {} }

const net = {};    // customerNo -> net past-due balance
const hasOld = {}; // customerNo -> has a remaining invoice dated <= CUTOFF
for (const e of entries) {
  const isOpen = e.Open === true || e.Open === 'true' || e.Open === 1;
  if (!isOpen) continue;
  const key = String(e.Customer_No);
  const remaining = Number(e.Remaining_Amount) || 0;
  const due = String(e.Due_Date || '').slice(0, 10);
  const doc = String(e.Document_Date || '').slice(0, 10);
  if (String(e.Document_Type) === 'Invoice') {
    if (remaining !== 0 && doc && (!CUTOFF || doc <= CUTOFF)) hasOld[key] = true;
    if (due && due < today) net[key] = (net[key] || 0) + remaining; // past-due invoice
  } else {
    net[key] = (net[key] || 0) + remaining; // open payment/credit (negative)
  }
}
// Counted: a remaining invoice dated 2024-or-older AND a net past-due balance that
// is positive AND at least the MIN threshold from the Settings node.
const nos = Object.keys(net).filter(
  (k) => hasOld[k] && Math.round(net[k] * 100) > 0 && Math.round(net[k] * 100) >= Math.round(MIN * 100)
);

// Nobody qualifies -> stop. On a webhook run, mark the job done-empty so the page
// stops waiting.
if (nos.length === 0) {
  try {
    let jobId = null; try { jobId = $('SW Make Job').first().json.jobId; } catch (e) {}
    if (jobId) { const sd = $getWorkflowStaticData('global'); sd['job_' + jobId] = { status: 'done', at: Date.now(), customers: 0, empty: true }; }
  } catch (e) {}
  return [];
}

// Chunk the customer numbers so each Get Customers request URL stays well under
// the length limit. ~40 numbers => a $filter of ~800 chars per request.
const CHUNK = 40;
const out = [];
for (let i = 0; i < nos.length; i += CHUNK) {
  const part = nos.slice(i, i + CHUNK);
  const customerFilter = part.map((n) => "No eq '" + n.replace(/'/g, "''") + "'").join(' or ');
  out.push({ json: { batch: i / CHUNK, count: nos.length, customerNos: part, customerFilter } });
}
return out;

/*
 * transform.js
 * ------------
 * Pure data transforms shared by the local test harness and the n8n Code node.
 * No I/O, no dependencies — safe to paste into an n8n Code node.
 *
 * Inputs (arrays of plain objects):
 *   customers[] (OData V4 Customer page):
 *     { No, Name, Address, Address_2, City, County, Post_Code, Balance_Due_LCY }
 *   entries[] (OData V4 CustomerLedgerEntries page — table 21):
 *     { Customer_No, Document_Type, Document_No, Document_Date, Due_Date,
 *       Amount, Remaining_Amount, Open }   // Open=true & Document_Type='Invoice' = unpaid invoice
 *
 * Output: one record per QUALIFYING customer (>=1 open invoice dated in the window):
 *   { customerNo, tokens{...seven merge tokens...}, statement{ lines[], total, balanceDue } }
 */

const WINDOW_START = "2023-01-01";
const WINDOW_END = "2024-12-31";

// Format a number as a USD amount WITHOUT the currency symbol: 1234.5 -> "1,234.50".
// The letter template already prints a literal "$" before {Converted_balance}.
function formatUSD(n) {
  const num = Number(n) || 0;
  return num.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

// Normalize a BC date (which may arrive as "2023-05-01" or full ISO) to YYYY-MM-DD.
function isoDate(d) {
  if (!d) return "";
  return String(d).slice(0, 10);
}

function inWindow(dateStr) {
  const d = isoDate(dateStr);
  return d >= WINDOW_START && d <= WINDOW_END;
}

// Map the BC Document_Type to a short label for the statement's "Document Type"
// column: Invoice / Credit / Payment / Refund (unknown types pass through as-is).
function displayDocType(type) {
  const t = String(type == null ? "" : type).trim();
  if (t === "Credit Memo" || t === "Credit") return "Credit";
  if (t === "Invoice") return "Invoice";
  if (t === "Payment") return "Payment";
  if (t === "Refund") return "Refund";
  return t;
}

/**
 * @param {Object[]} customers
 * @param {Object[]} entries     Customer Ledger Entries (OData V4 CustomerLedgerEntries)
 * @param {Object}   [options]
 * @param {string}   [options.today] ISO date used for the past-due test (default: today). An
 *        invoice is past due when its Due Date is strictly before this date.
 * @param {"filtered"|"balanceDue"} [options.amountSource="filtered"]
 *        "filtered"   -> Converted_balance = past-due invoices minus open credits/payments
 *        "balanceDue" -> Converted_balance = customer's Balance_Due_LCY (total open balance)
 *
 * Counted customers = those with a POSITIVE net past-due balance. The statement lists the
 * past-due invoices plus open credits/payments (negative lines); the total nets to the letter
 * amount.
 * @returns {Object[]} qualifying customer records
 */
function buildRecords(customers, entries, options = {}) {
  const amountSource = options.amountSource || "filtered";
  // "Past due" = an open invoice whose Due Date is strictly before `today`.
  const today = options.today || new Date().toISOString().slice(0, 10);
  // A customer is counted only if they have an open invoice with remaining balance
  // dated on/before this cutoff (default 2024 or older). BLANK ("") drops the age
  // rule so any overdue invoice qualifies.
  const qualifyCutoff = options.qualifyCutoff == null
    ? "2024-12-31"
    : String(options.qualifyCutoff).slice(0, 10);
  // Minimum net past-due balance to include a customer (default 0). The workflow's
  // "Settings" node sets this to 1000 so only customers owing >= $1,000 get a letter.
  const minBalance = Number(options.minBalance) || 0;

  // Index customers by their number for O(1) join.
  const custByNo = new Map();
  for (const c of customers || []) custByNo.set(String(c.No), c);

  // First ship-to per customer = the default; used for the shipping-address PDF.
  const shipByNo = new Map();
  for (const st of options.shipTos || []) {
    const k = String(st.HFSCustomerNo);
    if (!shipByNo.has(k)) shipByNo.set(k, st);
  }

  // Per customer, collect: PAST-DUE invoice lines, plus OPEN credit/payment lines
  // (any date). Non-invoice open entries (Payment/Credit Memo/Refund) are credits
  // with a negative Remaining_Amount that reduce the balance. `hasOld` flags an open
  // invoice with remaining dated on/before the qualify cutoff.
  const grouped = new Map(); // customerNo -> { lines[], total, hasOld }
  for (const e of entries || []) {
    const isOpen = e.Open === true || e.Open === "true" || e.Open === 1;
    if (!isOpen) continue;

    const type = String(e.Document_Type);
    const remaining = Number(e.Remaining_Amount) || 0;
    const documentDate = isoDate(e.Document_Date);
    const dueDate = isoDate(e.Due_Date);
    const key = String(e.Customer_No);
    if (!grouped.has(key)) grouped.set(key, { lines: [], total: 0, hasOld: false });
    const g = grouped.get(key);

    if (type === "Invoice") {
      // Qualify gate: an open invoice with a remaining balance dated <= cutoff.
      // Blank cutoff -> any remaining invoice satisfies the gate.
      if (remaining !== 0 && documentDate && (!qualifyCutoff || documentDate <= qualifyCutoff)) g.hasOld = true;
      // Statement shows only PAST-DUE invoices.
      if (dueDate && dueDate < today) {
        g.total += remaining;
        g.lines.push({
          documentDate, docType: "Invoice",
          orderNo: e.Description || "", documentNo: e.Document_No || "",
          dueDate, remaining, kind: "invoice",
        });
      }
    } else {
      // Open payment/credit/refund — an unapplied credit, included regardless of date.
      g.total += remaining;
      g.lines.push({
        documentDate, docType: displayDocType(type),
        orderNo: e.Order_No || "", documentNo: e.Document_No || "",
        dueDate, remaining, kind: "credit",
      });
    }
  }

  const records = [];
  for (const [customerNo, g] of grouped) {
    // Counted only if they have a remaining invoice dated 2024-or-older AND a
    // positive net past-due balance that meets the minimum threshold.
    if (!g.hasOld) continue;
    if (Math.round(g.total * 100) <= 0) continue;
    if (Math.round(g.total * 100) < Math.round(minBalance * 100)) continue;

    const c = custByNo.get(customerNo) || {};
    const balanceDue = Number(c.Balance_Due_LCY) || 0;
    const amount = amountSource === "balanceDue" ? balanceDue : g.total;
    const Converted_balance = formatUSD(amount);
    const name = c.Name || customerNo;

    const lines = g.lines.sort((a, b) =>
      a.documentDate < b.documentDate ? -1 : a.documentDate > b.documentDate ? 1 : 0
    );

    const tokens = {
      Description: name, AccountNumber: customerNo,
      Address_1: c.Address || "", Address_2: c.Address_2 || "",
      City: c.City || "", State: c.County || "", Zipcode: c.Post_Code || "",
      Converted_balance,
    };
    // Shipping tokens: default ship-to address (fall back to billing when none).
    const st = shipByNo.get(customerNo);
    const shipTokens = st
      ? {
          Description: name, AccountNumber: customerNo,
          Address_1: st.Address || "", Address_2: st.Address_2 || "",
          City: st.City || "", State: st.County || st.State || "", Zipcode: st.Post_Code || "",
          Converted_balance,
        }
      : { ...tokens };

    records.push({ customerNo, tokens, shipTokens, statement: { lines, total: g.total, balanceDue } });
  }

  // Deterministic order: by customer name.
  records.sort((a, b) => a.tokens.Description.localeCompare(b.tokens.Description));
  return records;
}

// --- n8n driver -------------------------------------------------------------
// Get Customers runs once per batch (chunked to keep each URL short), so combine
// the .value array from every Get Customers item.
const customers = $('Get Customers').all().flatMap((it) => {
  const j = it.json;
  return j.value || (Array.isArray(j) ? j : j && j.No ? [j] : []);
});
// Ship-to addresses (for the shipping-address PDF); combine every batch's .value.
let shipTos = [];
try {
  shipTos = $('Get Ship-to Addresses').all().flatMap((it) => {
    const j = it.json;
    return j.value || (Array.isArray(j) ? j : j && j.HFSCustomerNo ? [j] : []);
  });
} catch (e) { shipTos = []; }
const invResp = $('Get Open Invoices').first().json;
const entries = invResp.value || (Array.isArray(invResp) ? invResp : []);

// Per-run override from the HubSpot page ("SW Make Job", webhook runs only) beats
// the manual Settings node.
let ov = null; try { ov = $('SW Make Job').first().json; } catch (e) {}
let minBalance = 1000;
if (ov && ov.minBalance !== undefined && ov.minBalance !== '') { const m = Number(ov.minBalance); if (isFinite(m)) minBalance = m; }
else { try { const v = Number($('Settings').first().json.Min_Overdue_Balance); if (isFinite(v)) minBalance = v; } catch (e) {} }
let qualifyCutoff = '2024-12-31';
if (ov && ov.oldestInvoice !== undefined) { qualifyCutoff = String(ov.oldestInvoice).slice(0, 10); }
else { try { const v = $('Settings').first().json.Oldest_Open_Invoice; if (v !== undefined) qualifyCutoff = String(v == null ? '' : v).slice(0, 10); } catch (e) {} }

const records = buildRecords(customers, entries, { amountSource: 'filtered', shipTos, minBalance, qualifyCutoff });
return records.map((r) => ({ json: r }));

/*
 * pure-pdf.js
 * -----------
 * Zero-dependency PDF generator. Emits the past-due letter + statement as ONE
 * multi-page PDF per customer using the base-14 fonts (no embedding, no modules,
 * no external service) — so it runs inside an n8n Cloud Code node as-is.
 *
 * Exports buildCustomerPdf(tokens, statement, opts) -> Buffer.
 *
 * Font widths are approximated (slightly generous) purely for line-wrapping and
 * centering; glyph rendering itself is exact (the viewer uses the real metrics).
 */

// --- WinAnsi text encoding + PDF string escaping ---------------------------
function toWin(s) {
  return String(s == null ? "" : s)
    .replace(/–/g, "\x96") // en dash
    .replace(/—/g, "\x97") // em dash
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/…/g, "...");
}
function esc(s) {
  return toWin(s).replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
}

// Approximate glyph width in em units (generous, so lines never overflow).
function emWidth(ch) {
  if (ch === " ") return 0.3;
  if ("iljI.,:;'!|`".includes(ch)) return 0.3;
  if ("ftr()[]-".includes(ch)) return 0.4;
  if ("mwMW".includes(ch)) return 0.92;
  if (ch >= "A" && ch <= "Z") return 0.72;
  if (ch >= "0" && ch <= "9") return 0.56;
  return 0.53;
}
function approxWidth(s, size) {
  let w = 0;
  for (const ch of toWin(s)) w += emWidth(ch);
  return w * size;
}
function wrap(text, size, maxWidth) {
  const words = String(text).split(/\s+/);
  const lines = [];
  let cur = "";
  for (const w of words) {
    const trial = cur ? cur + " " + w : w;
    if (approxWidth(trial, size) > maxWidth && cur) {
      lines.push(cur);
      cur = w;
    } else cur = trial;
  }
  if (cur) lines.push(cur);
  return lines;
}

// --- content-stream draw helpers -------------------------------------------
// Fonts: F1 Helvetica, F2 Helvetica-Bold, F3 Times-Roman, F4 Times-Bold
function text(x, y, s, font, size, gray) {
  const col = gray != null ? `${gray} g ` : "0 g ";
  return `${col}BT /${font} ${size} Tf 1 0 0 1 ${x.toFixed(2)} ${y.toFixed(2)} Tm (${esc(s)}) Tj ET\n`;
}
function hline(x1, x2, y) {
  return `0.6 G 0.7 w ${x1.toFixed(2)} ${y.toFixed(2)} m ${x2.toFixed(2)} ${y.toFixed(2)} l S\n`;
}

const PAGE_W = 612, PAGE_H = 792, MARGIN = 72;
const HEAD = "ENGELMAN'S BAKERY";

// Embedded brand logo (baseline JPEG). Populated by scripts/embed-logo.js.
const LOGO = { w: 263, h: 53, b64: "" };

// Draw the letterhead centered at the top: the logo image if present, else grey text.
// Returns { content, bottom } where `bottom` is the y just below the header.
function header(topY, dispW, textSize) {
  if (LOGO && LOGO.b64) {
    const w = dispW;
    const h = dispW * (LOGO.h / LOGO.w);
    const x = (PAGE_W - w) / 2;
    const bottom = topY - h;
    const content =
      `q ${w.toFixed(2)} 0 0 ${h.toFixed(2)} ${x.toFixed(2)} ${bottom.toFixed(2)} cm /Im0 Do Q\n`;
    return { content, bottom };
  }
  const size = textSize || 22;
  const w = approxWidth(HEAD, size);
  return { content: text((PAGE_W - w) / 2, topY - size, HEAD, "F4", size, "0.5"), bottom: topY - size };
}

// --- letter (2 pages) -------------------------------------------------------
function letterPages(t) {
  const cw = PAGE_W - 2 * MARGIN;
  const size = 11, lh = 15;

  // Page 1
  const h1 = header(PAGE_H - MARGIN, 170, 22);
  let c = h1.content;
  let y = h1.bottom - 30;
  c += text(MARGIN, y, "Subject:", "F4", size);
  c += text(MARGIN + approxWidth("Subject:  ", size), y, "Past Due Balance – Immediate Attention Required", "F3", size);
  y -= lh + 12;
  c += text(MARGIN, y, `Dear ${t.Description},`, "F3", size);
  y -= lh + 12;

  const paras = [
    `We are writing to inform you that your account with Engelman's Bakery is currently past due. As of today, your overdue balance is $${t.Converted_balance}. We have enclosed an account statement for your convenience.`,
    "We kindly request that you remit payment in full to satisfy your payment obligation. Please contact us at 770-248-1444 ext. 2 to arrange payment or discuss any questions regarding your account. If the account is not paid, further collection proceedings will be taken.",
    "We appreciate your prompt attention to this matter and look forward to resolving it quickly.",
  ];
  for (const p of paras) {
    for (const ln of wrap(p, size, cw)) {
      c += text(MARGIN, y, ln, "F3", size);
      y -= lh;
    }
    y -= 10;
  }
  y -= 12;
  c += text(MARGIN, y, "Best Regards,", "F3", size); y -= lh;
  c += text(MARGIN, y, "Engelman's Bakery", "F3", size); y -= lh;
  c += text(MARGIN, y, "770-248-1444", "F3", size);

  // Page 2 — mailing address block (window-envelope position)
  let c2 = header(PAGE_H - MARGIN, 170, 22).content;
  const addr = [
    t.Description,
    t.Address_1,
    t.Address_2,
    cityStateZip(t),
  ].filter((l) => l && String(l).trim() && String(l).trim() !== ",");
  let ay = 150;
  for (const ln of addr) {
    c2 += text(MARGIN, ay, ln, "F3", size);
    ay -= lh;
  }
  return [c, c2];
}

// --- statement (1+ pages) ---------------------------------------------------
function formatUSD(n) {
  const num = Number(n) || 0;
  return num.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
// Signed dollar amount: 1234.5 -> "$1,234.50", -200 -> "-$200.00".
function money(n) {
  const num = Number(n) || 0;
  return (num < 0 ? "-$" : "$") + formatUSD(Math.abs(num));
}
// "City, State Zip" — omits the state/zip cleanly when missing (ship-to has no state).
function cityStateZip(t) {
  const cs = [t.City, t.State].filter((x) => x && String(x).trim()).join(", ");
  return [cs, t.Zipcode].filter((x) => x && String(x).trim()).join(" ");
}
function statementPages(t, statement, opts) {
  const asOf = (opts && opts.asOfDate) || new Date().toISOString().slice(0, 10);
  // Left edges spread evenly across the content width (72..540) so the six columns
  // are balanced — no left-side crowding and no dead gap before the right-aligned
  // Remaining Balance column.
  const cols = [
    { key: "documentDate", label: "Document Date", x: MARGIN },
    { key: "docType", label: "Document Type", x: MARGIN + 84 },
    { key: "documentNo", label: "Document No.", x: MARGIN + 164 },
    { key: "orderNo", label: "Order No.", x: MARGIN + 241 },
    { key: "dueDate", label: "Due Date", x: MARGIN + 339 },
    { key: "remaining", label: "Remaining Balance", x: MARGIN + 410, money: true, right: PAGE_W - MARGIN },
  ];
  const size = 8, lh = 14;

  const pages = [];
  let c = "";
  let y;
  const startPage = (withHeader) => {
    const hd = header(PAGE_H - MARGIN, 150, 20);
    c = hd.content;
    y = hd.bottom - 34; // extra space between the logo and the title
    const title = "Past Due Invoices";
    c += text((PAGE_W - approxWidth(title, 16)) / 2, y, title, "F4", 16);
    y -= 30;
    if (withHeader) {
      c += text(MARGIN, y, `Statement Date: ${asOf}`, "F1", 10); y -= 18;
      // Bill-to block: Company Name, Account Number, then address.
      const bill = [
        t.Description,
        t.AccountNumber ? "Account Number: " + t.AccountNumber : null,
        t.Address_1,
        t.Address_2,
        cityStateZip(t),
      ].filter((l) => l && String(l).trim() && String(l).trim() !== ",");
      for (const l of bill) { c += text(MARGIN, y, l, "F1", 10); y -= 13; }
      y -= 18;
    }
    // column header
    for (const col of cols) {
      if (col.right) c += text(col.right - approxWidth(col.label, size), y, col.label, "F2", size);
      else c += text(col.x, y, col.label, "F2", size);
    }
    y -= 5;
    c += hline(MARGIN, PAGE_W - MARGIN, y);
    y -= 13;
  };

  startPage(true);
  for (const ln of statement.lines) {
    if (y < 110) { pages.push(c); startPage(false); }
    for (const col of cols) {
      const v = col.money ? money(ln[col.key]) : String(ln[col.key] || "");
      if (col.right) c += text(col.right - approxWidth(v, size), y, v, "F1", size);
      else c += text(col.x, y, v, "F1", size);
    }
    y -= lh;
  }
  y -= 4;
  c += hline(MARGIN, PAGE_W - MARGIN, y);
  y -= 16;
  const totLabel = "Total Past Due:";
  const totVal = money(statement.total);
  c += text(MARGIN + 300, y, totLabel, "F2", 10);
  c += text((PAGE_W - MARGIN) - approxWidth(totVal, 10), y, totVal, "F2", 10);
  pages.push(c);
  return pages;
}

// --- low-level PDF assembler ------------------------------------------------
// Memory-conscious: streams every object into a chunk array (each chunk becomes a
// small Buffer, joined once at the end) instead of growing one multi-MB string,
// and frees each page's content as soon as it is serialized. This keeps peak
// memory near one copy of the output — important for large batches inside the
// memory-capped n8n Cloud Code node. All emitted text is latin1 (bytes 0-255),
// so a string's .length equals its byte length and can drive the xref offsets.
function buildPdf(pageContents, docOpts) {
  const title = docOpts && docOpts.title;
  const P = pageContents.length;
  const offsets = [];
  const chunks = [];
  let pos = 0;
  const push = (s) => { chunks.push(s); pos += s.length; };
  push("%PDF-1.4\n%\xe2\xe3\xcf\xd3\n");
  const emit = (num, body) => {
    offsets[num] = pos;
    push(`${num} 0 obj\n${body}\nendobj\n`);
  };
  // Optional logo image XObject is object 7; content/page objects start after it.
  const hasLogo = !!(LOGO && LOGO.b64);
  const imgObj = 7;
  const base = hasLogo ? 7 : 6; // last non-page object number
  const xobjRes = hasLogo ? ` /XObject << /Im0 ${imgObj} 0 R >>` : "";

  const pageNums = [];
  for (let i = 0; i < P; i++) pageNums.push(base + 2 + i * 2);

  emit(1, "<< /Type /Catalog /Pages 2 0 R >>");
  emit(2, `<< /Type /Pages /Kids [ ${pageNums.map((n) => n + " 0 R").join(" ")} ] /Count ${P} >>`);
  emit(3, "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
  emit(4, "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");
  emit(5, "<< /Type /Font /Subtype /Type1 /BaseFont /Times-Roman /Encoding /WinAnsiEncoding >>");
  emit(6, "<< /Type /Font /Subtype /Type1 /BaseFont /Times-Bold /Encoding /WinAnsiEncoding >>");
  if (hasLogo) {
    const jpeg = Buffer.from(LOGO.b64, "base64").toString("latin1");
    emit(
      imgObj,
      `<< /Type /XObject /Subtype /Image /Width ${LOGO.w} /Height ${LOGO.h} ` +
        `/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\n` +
        `stream\n${jpeg}\nendstream`
    );
  }
  for (let i = 0; i < P; i++) {
    const contentNum = base + 1 + i * 2;
    const pageNum = base + 2 + i * 2;
    const content = pageContents[i];
    pageContents[i] = null; // release the source string once we've consumed it
    emit(contentNum, `<< /Length ${content.length} >>\nstream\n${content}\nendstream`);
    emit(
      pageNum,
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_W} ${PAGE_H}] ` +
        `/Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R /F4 6 0 R >>${xobjRes} >> /Contents ${contentNum} 0 R >>`
    );
  }
  // Optional document Title (shows in the PDF viewer's title bar / tab).
  let infoObj = 0;
  if (title) {
    infoObj = base + 2 * P + 1;
    emit(infoObj, `<< /Title (${esc(title)}) >>`);
  }
  const lastObj = base + 2 * P + (infoObj ? 1 : 0);
  const xrefOffset = pos;
  let xref = `xref\n0 ${lastObj + 1}\n0000000000 65535 f \n`;
  for (let n = 1; n <= lastObj; n++) {
    xref += String(offsets[n] || 0).padStart(10, "0") + " 00000 n \n";
  }
  push(xref);
  const infoRef = infoObj ? ` /Info ${infoObj} 0 R` : "";
  push(`trailer\n<< /Size ${lastObj + 1} /Root 1 0 R${infoRef} >>\nstartxref\n${xrefOffset}\n%%EOF\n`);
  // Join once. Small per-chunk Buffers avoid a giant intermediate latin1 string.
  const out = Buffer.concat(chunks.map((c) => Buffer.from(c, "latin1")));
  chunks.length = 0;
  return out;
}

// Page-content array for one customer: the letter (sheet 1) then the statement
// (sheet 2). For double-sided printing each block is padded to an EVEN page count,
// so every account is 4 pages (letter=2, statement=2) and the letters always land
// on pages 1, 5, 9, ... A longer statement (3+ pages) still stays even.
// Null-safe: a missing tokens/statement can never throw (renders empty fields).
function customerPages(tokens, statement, opts) {
  const o = opts || {};
  const pad = o.pad !== false; // pad:false -> compact copy (no blank filler pages)
  const t = tokens || {};
  const s = statement && statement.lines ? statement : { lines: [], total: 0 };
  const letter = letterPages(t);
  if (pad && letter.length % 2 === 1) letter.push(""); // pad the letter to a full sheet
  const stmt = statementPages(t, s, o);
  if (pad && stmt.length % 2 === 1) stmt.push(""); // pad the statement to a full sheet
  return [...letter, ...stmt];
}

// Normalize an address token set to a comparable key (case/space-insensitive).
function normAddr(t) {
  const x = t || {};
  return [x.Address_1, x.Address_2, x.City, x.State, x.Zipcode]
    .map((v) => String(v == null ? "" : v).trim().toLowerCase())
    .join("|");
}
// True when two token sets carry the same mailing address (ignores Description).
// Used to skip customers whose shipping address equals billing from the shipping PDF.
function sameAddress(a, b) {
  return normAddr(a) === normAddr(b);
}

// One PDF (letter + statement) for a single customer.
function buildCustomerPdf(tokens, statement, opts) {
  return buildPdf(customerPages(tokens, statement, opts));
}

// One combined batch PDF for a list of records. tokenKey selects the address set:
// "tokens" (billing, default) or "shipTokens" (shipping).
function buildBatchPdf(records, opts, tokenKey) {
  const key = tokenKey || "tokens";
  const pages = [];
  for (const r of records || []) {
    const tok = r && (r[key] || r.tokens);
    if (!tok) continue; // skip malformed records instead of crashing
    pages.push(...customerPages(tok, r.statement, opts));
  }
  return buildPdf(pages, opts);
}

// --- n8n driver -------------------------------------------------------------
// Build ONE combined PDF for the whole run: for each customer, the letter pages
// then that customer's statement pages, in customer order ->
//   Letter 1, Statement 1, Letter 2, Statement 2, ...
const all = items.map((i) => i.json);
// Defensive: only render records that actually carry tokens, so one malformed or
// stale item can never crash the whole batch. 'skipped' surfaces any bad input.
const records = all.filter((r) => r && r.tokens);
const skipped = all.length - records.length;

// The billing PDF has every qualifying customer. The shipping PDF has ONLY the
// customers whose shipping address differs from their billing address — when the
// two match (or there's no ship-to), that customer appears in the billing PDF only.
const shippingRecords = records.filter((r) => r.shipTokens && !sameAddress(r.tokens, r.shipTokens));

// Double-sided padding on by default; the page can turn it off (pad:false) for a
// compact, screen/one-sided copy with no blank filler pages.
let pad = true;
try { const ovj = $('SW Make Job').first().json; if (ovj && ovj.pad === false) pad = false; } catch (e) {}

// Two combined PDFs (billing + shipping). Filenames and PDF /Title both carry the date.
// Build one PDF at a time and hand it straight to prepareBinaryData (which offloads
// the bytes to n8n's binary store) BEFORE building the next, so we never hold two
// multi-MB buffers at once — keeps the Code node under its memory cap on big batches.
const today = new Date().toISOString().slice(0, 10);
const billingName = 'Past-Due-Billing-' + today + '.pdf';
const shippingName = 'Past-Due-Shipping-' + today + '.pdf';
const billingData = await this.helpers.prepareBinaryData(
  buildBatchPdf(records, { title: 'Past-Due Billing ' + today, pad }, 'tokens'),
  billingName, 'application/pdf');
const shippingData = await this.helpers.prepareBinaryData(
  buildBatchPdf(shippingRecords, { title: 'Past-Due Shipping ' + today, pad }, 'shipTokens'),
  shippingName, 'application/pdf');
return [
  {
    json: { type: 'billing', customers: records.length, skipped, fileName: billingName },
    binary: { data: billingData },
  },
  {
    json: { type: 'shipping', customers: shippingRecords.length, skipped, fileName: shippingName },
    binary: { data: shippingData },
  },
];

